/**
 * Types shared with contracts generated by `php artisan bridge:generate`.
 *
 * A generated contract looks like:
 *
 * ```ts
 * export interface AppBridge {
 *   operations: { 'products.list': { input: { page?: number }; output: Paginated<Product> } };
 *   events: { 'orders.updated': { channel: 'private'; payload: { id: number } } };
 * }
 * ```
 */

/** How an operation may be retried. See PROTOCOL.md, "Idempotency". */
export type IdempotencyLevel = 'safe' | 'idempotent' | 'unsafe';

/** Whether an operation needs a signed-in user. */
export type OperationAuth = 'guest' | 'user';

/** The kind of broadcast channel an event travels on. */
export type ChannelType = 'public' | 'private' | 'presence';

/** One operation's types. */
export interface OperationShape {
  input: unknown;
  output: unknown;
}

/** One realtime event's types. */
export interface EventShape {
  channel: ChannelType;
  payload: unknown;
}

/** The shape every generated contract satisfies. */
export interface Contract {
  operations: { [operation: string]: OperationShape };
  events?: { [event: string]: EventShape };
}

/** Used when no contract is given: any operation, untyped input and output. */
export interface UntypedContract extends Contract {
  operations: { [operation: string]: { input: Record<string, unknown> | undefined; output: unknown } };
  events: { [event: string]: { channel: ChannelType; payload: unknown } };
}

/** Runtime metadata for one operation, emitted as the generated `operations` constant. */
export interface OperationInfo {
  readonly idempotency: IdempotencyLevel;
  readonly auth: OperationAuth;
  readonly deprecated?: string | false;
}

/** The generated `operations` constant. */
export type OperationsManifest = { readonly [operation: string]: OperationInfo };

export type OperationName<C extends Contract> = Extract<keyof C['operations'], string>;
export type InputOf<C extends Contract, K extends OperationName<C>> = C['operations'][K]['input'];
export type OutputOf<C extends Contract, K extends OperationName<C>> = C['operations'][K]['output'];

type Events<C extends Contract> = NonNullable<C['events']>;
export type EventName<C extends Contract> = Extract<keyof Events<C>, string>;
export type EventPayload<C extends Contract, E extends EventName<C>> = Events<C>[E] extends { payload: infer P }
  ? P
  : never;
export type EventChannel<C extends Contract, E extends EventName<C>> = Events<C>[E] extends {
  channel: infer T extends ChannelType;
}
  ? T
  : never;

/** True when `I` has no required keys, so the input argument can be left out. */
export type HasOptionalInput<I> = [I] extends [undefined] ? true : Record<string, never> extends I ? true : false;

/** Pagination metadata. `type` tells which Laravel paginator produced it. */
export type Pagination = LengthAwarePagination | SimplePagination | CursorPagination;

export interface LengthAwarePagination {
  type: 'length_aware';
  per_page: number;
  current_page: number;
  has_more: boolean;
  total: number;
  last_page: number;
}

export interface SimplePagination {
  type: 'simple';
  per_page: number;
  current_page: number;
  has_more: boolean;
}

export interface CursorPagination {
  type: 'cursor';
  per_page: number;
  has_more: boolean;
  next_cursor: string | null;
  prev_cursor: string | null;
}

/** A paginated output. */
export interface Paginated<T> {
  items: T[];
  pagination: Pagination;
}

/** A signed, expiring download link returned by an operation. */
export interface DownloadLink {
  url: string;
  name: string;
  expires_at: string;
}

/** A file as React Native's `FormData` accepts it (for example from an image picker). */
export interface ReactNativeFile {
  uri: string;
  name: string;
  type: string;
}

/** Anything that can be uploaded as an operation input. */
export type BridgeFile = Blob | ReactNativeFile;

/** The `meta` object on every Bridge response. */
export interface ResponseMeta {
  request_id: string;
  version: string;
  operation?: string;
  deprecated?: { message: string };
  idempotent_replay?: boolean;
  [key: string]: unknown;
}

/** A successful call with its metadata, as returned by `callRaw`. */
export interface BridgeResponse<T> {
  data: T;
  meta: ResponseMeta;
  status: number;
  headers: Headers;
}
